//! Shared by the integration tests that replay the House patch fixture
//! (`house_patches.rs`, `no_alloc.rs`, `perf.rs`).
//!
//! `fixtures/house_patches.txt` is generated by
//! `app/src/state/patches.fixture.test.ts` from `app/src/state/housePatches.ts`
//! (`UPDATE_FIXTURES=1 npx vitest run app/src/state/patches.fixture.test.ts`).
//! Per patch: `patch <name>`, `phrase <chord4|chord5|bass|lead|arp|fx>`, its
//! example roll if it has one (`example <bars>`, then `note <pitch> <vel>
//! <start> <len>` per note, ticks at 960 PPQ; plan 28), then the exact
//! commands the UI sends to add a synth track (slot 0) holding it, one
//! `op a b c d` per line.
#![allow(dead_code)]

pub const HOUSE_FIXTURE: &str = include_str!("../fixtures/house_patches.txt");

/// What the level, peak and CPU tests play on a patch (plan 11 *The House set*).
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Phrase {
    /// C4 E4 G4 B4 (keys and stabs).
    Chord4,
    /// C3 G3 C4 E4 B4 (pads).
    Chord5,
    /// C2, then C3 (mono).
    Bass,
    /// C4 (mono).
    Lead,
    /// C4 E4 G4 B4 as 1/16 notes at 124 BPM, one bar (each note held its
    /// full 1/16): how an arp patch is played.
    Arp,
    /// C4 (mono): a transition effect (plan 28: Noise Sweep, Impact). Not
    /// part of the level / clip / release loops: those patches are played
    /// by the Transition tracks with their own automation and are measured
    /// by their own tests.
    Fx,
}

/// The 1/16 note at the default 124 BPM (s).
pub const SIXTEENTH_124: f32 = 60.0 / 124.0 / 4.0;

impl Phrase {
    /// The phrase's notes as successive chords (a mono phrase is one note per
    /// step; a poly phrase is one chord).
    pub fn steps(self) -> &'static [&'static [u8]] {
        match self {
            Phrase::Chord4 => &[&[60, 64, 67, 71]],
            Phrase::Chord5 => &[&[48, 55, 60, 64, 71]],
            Phrase::Bass => &[&[36], &[48]],
            Phrase::Lead | Phrase::Fx => &[&[60]],
            Phrase::Arp => &[
                &[60], &[64], &[67], &[71], &[60], &[64], &[67], &[71],
                &[60], &[64], &[67], &[71], &[60], &[64], &[67], &[71],
            ],
        }
    }
    /// The phrase's own step length (s), if it has one (an arp's 1/16);
    /// otherwise the test picks a hold.
    pub fn step(self) -> Option<f32> {
        match self {
            Phrase::Arp => Some(SIXTEENTH_124),
            _ => None,
        }
    }
    pub fn mono(self) -> bool {
        matches!(self, Phrase::Bass | Phrase::Lead | Phrase::Fx)
    }
}

/// One note of an example roll: ticks at 960 PPQ.
#[derive(Clone, Copy, Debug)]
pub struct RollNote {
    pub pitch: u8,
    pub vel: u8,
    pub start: u32,
    pub len: u32,
}

/// A patch's example roll (`houseExamples.ts`).
#[derive(Clone, Debug)]
pub struct Example {
    pub bars: u32,
    pub notes: Vec<RollNote>,
}

pub struct HousePatch {
    pub name: String,
    pub phrase: Phrase,
    pub example: Option<Example>,
    pub cmds: Vec<[f64; 5]>,
}

/// Every patch of the fixture, in order. Panics on a patch without a
/// `phrase` line (a stale or hand-edited fixture), rather than guessing one.
pub fn house_patches() -> Vec<HousePatch> {
    // Blocks as parsed: the phrase is checked once the block is complete.
    struct Block {
        name: String,
        phrase: Option<Phrase>,
        example: Option<Example>,
        cmds: Vec<[f64; 5]>,
    }
    let mut out: Vec<Block> = Vec::new();
    for line in HOUSE_FIXTURE.lines() {
        let line = line.trim();
        if line.is_empty() || line.starts_with('#') {
            continue;
        }
        if let Some(name) = line.strip_prefix("patch ") {
            out.push(Block { name: name.to_string(), phrase: None, example: None, cmds: Vec::new() });
            continue;
        }
        let last = out.last_mut().expect("line before the first patch");
        if let Some(p) = line.strip_prefix("phrase ") {
            assert!(last.phrase.is_none(), "patch {:?} has two phrase lines", last.name);
            last.phrase = Some(match p {
                "chord4" => Phrase::Chord4,
                "chord5" => Phrase::Chord5,
                "bass" => Phrase::Bass,
                "lead" => Phrase::Lead,
                "arp" => Phrase::Arp,
                "fx" => Phrase::Fx,
                other => panic!("unknown phrase {other:?}"),
            });
            continue;
        }
        if let Some(b) = line.strip_prefix("example ") {
            assert!(last.example.is_none(), "patch {:?} has two example lines", last.name);
            last.example = Some(Example { bars: b.parse().expect("bars"), notes: Vec::new() });
            continue;
        }
        if let Some(n) = line.strip_prefix("note ") {
            let v: Vec<u32> = n.split_whitespace().map(|x| x.parse().expect("note field")).collect();
            assert_eq!(v.len(), 4, "bad note line {line:?}");
            let ex = last.example.as_mut().unwrap_or_else(|| panic!("note before example in {:?}", last.name));
            ex.notes.push(RollNote { pitch: v[0] as u8, vel: v[1] as u8, start: v[2], len: v[3] });
            continue;
        }
        let nums: Vec<f64> = line.split_whitespace().map(|x| x.parse().expect("number")).collect();
        assert_eq!(nums.len(), 5, "bad fixture line {line:?}");
        last.cmds.push([nums[0], nums[1], nums[2], nums[3], nums[4]]);
    }
    out.into_iter()
        .map(|b| {
            let phrase = b.phrase.unwrap_or_else(|| panic!("house patch {:?} has no phrase line in the fixture", b.name));
            HousePatch { name: b.name, phrase, example: b.example, cmds: b.cmds }
        })
        .collect()
}
